targets.query:
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "station_acquisition" and r.station_id == "${station}" and r._field == "age_seconds")
  |> last()
  |> map(fn: (r) => ({
      _time: r._time,
      _value: if r.status == "error" or r._value > 300.0 then 2 else if r.status == "warning" then 1 else 0
  }))
